"""Original offline report identity. No external fonts, assets or vendor logos."""
import html


def masthead(context):
    return '''<header class="masthead"><div class="identity"><svg class="guard-mark" width="38" height="38" viewBox="0 0 38 38" aria-hidden="true"><path d="M8 8v22M8 19h12l10-11M20 19l10 11" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="8" cy="8" r="4" fill="currentColor"/><circle cx="8" cy="30" r="4" fill="currentColor"/><circle cx="30" cy="8" r="4" fill="currentColor"/><circle cx="30" cy="30" r="4" fill="#c13d2c"/></svg><div class="wordmark">Salesforce Guard<span>''' + html.escape(context) + '''</span></div></div><div class="review-mode">REVIEW MODE<span>No deployment actions</span></div></header>'''


REPORT_CSS='''
:root{color-scheme:light;--bg:#f4f2e9;--panel:#fffef8;--border:#d3d8c9;--muted:#596b61;--ink:#172d25;--mint:#236549;--accent:#d8ed79;--danger:#b73224}
html{scroll-behavior:auto;scroll-padding-top:20px}body{background:var(--bg);color:var(--ink);font-family:Arial,"Segoe UI",sans-serif;font-size:15px;line-height:1.65}*{box-sizing:border-box}main{max-width:1240px;margin:auto;padding:28px 38px 68px}
.masthead{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-bottom:24px;margin-bottom:36px;border-bottom:1px solid var(--ink)}.identity{display:flex;align-items:center;gap:12px}.guard-mark{flex:none}.wordmark{font-size:19px;font-weight:750;letter-spacing:-.035em;line-height:1.15}.wordmark span{display:block;font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);font-weight:600;margin-top:7px}.review-mode{text-align:right;font-size:10px;letter-spacing:.13em;font-weight:750}.review-mode span{display:block;font-size:11px;letter-spacing:0;font-weight:400;color:var(--muted);margin-top:4px}
h1{font-family:Georgia,"Times New Roman",serif;font-weight:400;font-size:clamp(46px,6.6vw,84px);line-height:1.01;letter-spacing:-.055em;margin:12px 0 24px}h1 em{font-weight:400;color:#32624a}h2{font-size:24px;letter-spacing:-.035em;font-weight:700;margin:40px 0 16px}h3{letter-spacing:-.02em}p{max-width:920px}.intro{font-size:17px;line-height:1.65;max-width:700px}.eyebrow{font-size:10px;font-weight:750;letter-spacing:.17em;text-transform:uppercase;color:var(--muted);margin:0 0 12px}.hero-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(270px,1fr);gap:44px;align-items:center;margin-bottom:32px}.hero-grid h1{font-size:clamp(48px,5.6vw,76px)}
.review-card{background:var(--ink);color:#fffef8;padding:26px;border-radius:3px;box-shadow:9px 9px 0 #dce2cf;min-width:0}.review-card .eyebrow{color:#d8ed79}.review-card .component-name{font:16px/1.5 Consolas,monospace;overflow-wrap:anywhere;color:#fffef8}.reference-score{display:flex;align-items:center;gap:16px;margin:20px 0}.reference-score b{font:72px/.9 Georgia,serif;letter-spacing:-.06em;color:#d8ed79}.reference-score span{font-size:14px;color:#e0e7da;max-width:170px}.review-card p{font-size:13px;color:#c6d2c8}.review-card button{background:#d8ed79;color:#172d25;border:0;font-weight:700;padding:12px 18px}.review-card button:hover{background:#e6f3a9}
.banner{background:#e9eddf;border:0;border-left:3px solid #66794e;border-radius:0;padding:14px 18px;font-size:13px;margin:24px 0}.banner strong{font-weight:700}.metrics{background:transparent;gap:0;border-top:1px solid var(--ink);border-bottom:1px solid var(--ink);margin:28px 0 36px}.metric{background:transparent;border:0;border-right:1px solid var(--border);border-radius:0;padding:18px 20px;box-shadow:none}.metric:first-child{padding-left:0}.metric:last-child{border:0}.metric b{font:38px/1.1 Georgia,serif;color:var(--ink)}.metric span{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
.panel,.finding,section.wrap{background:var(--panel);border:1px solid var(--border);border-radius:3px;box-shadow:none}.finding{border-left:3px solid #9bbaa5;padding:22px}.finding:has(.pill.high){border-left-color:var(--danger)}.pill,.badge{border-radius:3px;font-size:11px;letter-spacing:.02em}.high,tr[data-change=destructive] .badge{color:#922c20;background:#fbe4dc;border-color:#e9b6a8}.medium,tr[data-change=unknown] .badge,tr[data-change=conflict] .badge{color:#785212;background:#f7eccb;border-color:#d8c78d}.low{color:#285747;background:#e2eee2;border-color:#b9d0b9}.muted,.location{color:var(--muted)}a,summary{color:#236549}summary{font-weight:600}pre{background:#edf0e4;color:#244e3c;border:1px solid #d3ddcb;border-radius:3px}input,select,button{background:#fffef8;color:var(--ink);border:1px solid #a9b8a5;border-radius:3px}button{font-weight:600}button:hover{background:#eef3df}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #85ad3b;outline-offset:3px}th{color:#536959;font-size:11px;text-transform:uppercase;letter-spacing:.06em}th,td{border-color:var(--border)}.allowed{color:#206044}.denied{color:#a83327}.unknown{color:#805a13}footer{border-top:1px solid var(--border);padding-top:18px;color:var(--muted)}
.impact-map{background:#0c1b18;border-color:#293e33;border-radius:3px}.impact-legend{color:#256244}.impact-legend .conditional{color:#805a13}.impact-legend .unresolved{color:#a83327}.impact-link,button.inspect-impact{background:#edf3df;border-color:#b4c6ac;color:#264f35;border-radius:3px}.impact-control{color:var(--muted)}.impact-connections{border-top:1px solid var(--border)}#impact-evidence pre{background:#edf0e4;color:#244e3c}
@media(max-width:750px){td::before{color:var(--muted)}main{padding:22px 18px 44px}.masthead{margin-bottom:28px}.hero-grid{grid-template-columns:1fr;gap:20px}.hero-grid h1{font-size:54px}.review-card{box-shadow:5px 5px 0 #dce2cf}.metric{padding:15px 10px}.metric:first-child{padding-left:10px}.metrics{row-gap:0}.wordmark{font-size:17px}.review-mode{font-size:9px}.review-mode span{font-size:10px}h1{font-size:48px}.intro{font-size:15px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:#fff}.review-card{background:#fff;color:#172d25;border:1px solid #172d25;box-shadow:none}.review-card .component-name,.review-card p,.reference-score b,.reference-score span,.review-card .eyebrow{color:#172d25}.masthead{margin-bottom:20px}h1{font-size:42px}}
'''
